<?php require __DIR__.'/_layout_start.php'; ?><h1>Utenti e accessi</h1><p class="page-lead">Amministratori, ruoli e ultimi accessi.</p><div class="table-wrap"><table><thead><tr><th>Utente</th><th>Email</th><th>Ruolo</th><th>Stato</th><th>Ultimo accesso</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><strong><?= htmlspecialchars(trim($row['first_name'].' '.$row['last_name']),ENT_QUOTES,'UTF-8') ?></strong><br><span class="muted"><?= htmlspecialchars($row['username'],ENT_QUOTES,'UTF-8') ?></span></td><td><?= htmlspecialchars($row['email'],ENT_QUOTES,'UTF-8') ?></td><td><span class="badge"><?= htmlspecialchars($row['role'],ENT_QUOTES,'UTF-8') ?></span></td><td><?= !empty($row['active'])?'Attivo':'Disabilitato' ?></td><td><?= !empty($row['last_login_at'])?htmlspecialchars(date('d/m/Y H:i',strtotime((string)$row['last_login_at'])),ENT_QUOTES,'UTF-8'):'Mai' ?></td></tr><?php endforeach; ?></tbody></table></div><?php require __DIR__.'/_layout_end.php'; ?>
